  const branchWeights = activeBranches.map((branch, index) => branch.code === 'Q3' ? 59 : branch.code === 'Q1' ? 41 : 32 + index * 3);
  const totalWeight = branchWeights.reduce((sum, value) => sum + value, 0) || 1;
